$('.livechat-desktop.livechat-offline').hover(function(){
	if($('.livechat-desktop.livechat-online').length == 1){
		$(".livechat-more").slideDown();
		$('.livechat-more').addClass('livechat-more-active');
		$(this).css('border-top', '0px solid');
	}
	else{
		$(".livechat-more-mobile").slideDown();
		$('.livechat-more-mobile').addClass('livechat-more-active-mobile');
		$(this).css('border-top', '0px solid');
	}
	
	}, function(){
		$(".livechat-more").slideUp();
		$('.livechat-more').removeClass('livechat-more-active');
		$(".livechat-more-mobile").slideUp();
		$('.livechat-more-mobile').removeClass('livechat-more-active-mobile');
		$(this).css('border-top', '1px solid');
	}
)

