var gMenuProductTop = '';

function menuProductOnScroll() {
    if($("#main-menu-product").length < 1) return false;

    // Menu on scroll
    var menu = document.getElementById('main-menu-product');
    var menuH = menu.offsetHeight + menu.offsetTop;
    if(!gMenuProductTop == '') gMenuProductTop = menu.offsetTop;

    if($(window).scrollTop() > menuH) {
        $('header').css({"margin-top": menu.offsetHeight});
        $(menu).addClass('sticky-menu');
    }

    if($(window).scrollTop() <= gMenuProductTop) {
        $('header').css({"margin-top": 0});
        $(menu).removeClass('sticky-menu');
    }
}

menuProductOnScroll();

$(window).scroll(function() {
    menuProductOnScroll();
});
$(window).resize(function() {
    menuProductOnScroll();
});

// request to server
function req(data, callback) {
	var xhttp = new XMLHttpRequest(),
		params = data['data'],
		formData = [],
		key;
	xhttp.onreadystatechange = function() {
		if (this.readyState == 4 && this.status == 200) {
			callback(xhttp.responseText);
		}
	};
	// generate data
	for (key in params) {
		formData.push(key + '=' + params[key]);
	}
	formData = formData.length ? formData.join('&') : '';
	// send
	xhttp.open("POST", data['url'], true);
	xhttp.setRequestHeader('Content-type', 'application/x-www-form-urlencoded');
	xhttp.send(formData);
}

function parseURLParams(url) {
    var queryStart = url.indexOf("?") + 1,
        queryEnd   = url.indexOf("#") + 1 || url.length + 1,
        query = url.slice(queryStart, queryEnd - 1),
        pairs = query.replace(/\+/g, " ").split("&"),
        parms = {}, i, n, v, nv;

    if (query === url || query === "") return;

    for (i = 0; i < pairs.length; i++) {
        nv = pairs[i].split("=", 2);
        n = decodeURIComponent(nv[0]);
        v = decodeURIComponent(nv[1]);

        if (!parms.hasOwnProperty(n)) parms[n] = '';
        parms[n] = nv.length === 2 ? v : null;
    }
    return parms;
}

function closeCampaign() {
	var modal = document.getElementById('modal-campaign');
	modal.parentNode.removeChild(modal);
}

function utmCampaign() {
	var getDataUrl = parseURLParams(window.location.href),
		wHeight = window.innerHeight - 30;

	if(typeof getDataUrl !== 'undefined' && (getDataUrl['utm_source'] || getDataUrl['utm_medium'] || getDataUrl['utm_campaign'] || getDataUrl['utm_term'] || getDataUrl['utm_content'])) {
		req({
			url: '/api/utm-campaign',
			data: getDataUrl
		}, function(response) {
			response = JSON.parse(response);

			if (response['Status'] == 1 && response['Data']['Image']) {
				// create html for campaign
				var html = '<div class="modal fade custom-modal in show" id="modal-campaign" tabindex="-1" role="dialog" style="display:block;">\
						        <div class="modal-dialog" role="document">\
						            <div class="modal-content">\
						                <div class="modal-body modal-campaign-body">\
						                	<div class="box-image">\
						                	<button type="button" class="close" data-dismiss="modal" aria-label="Close" onclick="closeCampaign()"><span aria-hidden="true">&times;</span></button>';

				if (response['Data']['Url']) {
					html += '<a href="'+ response['Data']['Url'] +'">';					
				}
					html += '<img src="'+ response['Data']['Image'] +'" style="max-height:'+ wHeight +'px;" />';

				if (response['Data']['Url']) {
					html += '</a>';					
				}
					html += '        	</div>\
										</div>\
						            </div>\
						        </div>\
						    </div>';

				var node = document.createElement('div');
			    node.innerHTML += html;

			    document.body.appendChild(node);
			}
		});
	}
}

window.onclick = function(event) {
	var modal = document.getElementById('modal-campaign');
    if (event.target == modal) {
        closeCampaign();
    }
}

utmCampaign();

// set floating social media agent
function floatingChat() {
	var agent = SessionStorage.get("Agent");
	var loginAgent = false;

	if(agent && agent['Detail'] && !loginAgent) {
		var menu_list = '';
		if(agent['Detail']['Skype']) {
			menu_list += `<li>
				<a class="skype" href="skype:${agent['Detail']['Skype']}?chat">
					<div class='icon'><i class='fab fa-skype'></i></div>
        			<div class='text'><span>Skype</span></div>
				</a>
			</li>`;
		}
		if(agent['Detail']['MobilePhone']) {
			menu_list += `<li>
				<a class="phone" href="tel:${agent['Detail']['MobilePhone']}">
					<div class='icon'><i class='fas fa-phone'></i></div>
        			<div class='text'><span>Phone</span></div>
				</a>
			</li>`;
		}
		if(agent['Detail']['Whatsapp']) {
			menu_list += `<li>
				<a class="whatsapp" href="https://wa.me/${agent['Detail']['Whatsapp']}" target="_blank">
					<div class='icon'><i class='fab fa-whatsapp'></i></div>
        			<div class='text'><span>Whatsapp</span></div>
				</a>
			</li>`;
		}
		if(menu_list) {
			var htmlSosmed = '<div class="sosmed"><ul>'+ menu_list +'</ul></div>\
								<div class="icon">\
									<img src="https://mypage.axa.co.id/dist/images/icons/chat-icon.svg" alt="Chat With Us" />\
									<span class="text">Live Chat</span>\
								</div>';
			$('#livechat').append(htmlSosmed);

			$('body').on('click', '#livechat', function() {
				if($(this).find('.sosmed').length) $(this).toggleClass('hide-sosmed');
			});

			hideLiveChat();
		}
	}
	else {
		var getId = document.getElementById('floating-menu-agent');
		if(getId) getId.remove();
		if(!loginAgent) {
			hideLiveChat('show');
		}
		else {
			hideLiveChat();
		}
	}

	if(loginAgent) hideLiveChat();
};
// hide livechat
function hideLiveChat(n='hide') {
	var livechat = [].slice.call(document.getElementsByClassName('livechat-b2c'));
	livechat.map(val => val && n == 'hide'? val.classList.add('hide') : val.classList.remove('hide'));
};

// update product url for b2b2c
function updateMenu() {
	var headerMenu = SessionStorage.get("headerMenu");
	var menuList = [].slice.call(document.querySelectorAll('.product-anchor'));
	var loginAgent = false;
	
	if(headerMenu != undefined) {
		var productList = headerMenu['userLicense'];

		// update href
		menuList.map(menu => {
			var url = menu.getAttribute('href');
			var product = menu.getAttribute('product');
			if(!productList.includes(product)) {
				var parent = menu.closest('.header-menu-item');
				menu.remove();
				// if it doesnt have anchor anymore then remove parent
				if(parent != null && !parent.getElementsByClassName('product-anchor').length) {
					parent.remove();
				}
			}
			else {
				// check if it doesnt have managedby then add it
				if(url.indexOf(`${headerMenu['managedBy']}`) < 0) {
					url = url.replace(/\/$/, '');
					menu.href = url+`/@${headerMenu['managedBy']}`;
				}
			}
		});

		if(!loginAgent) {
			// remove login
			var menu = [].slice.call(document.querySelectorAll('.login-menu'));
			menu.map(login => login.remove());
			// remove news
			var getNews = [].slice.call(document.querySelectorAll('a[href="/news"]'));
			if(getNews.length>0) {
				getNews.map(news => {
					var li = news.closest('li');
					if(li) li.remove();
				});
			}
		}
	}
}
updateMenu();

